// Shared engine helper: the first tracked Chrome-extension manifest
// (a manifest.json declaring manifest_version) — a structural primitive the
// extension technology packs build their checks and fingerprint on.
export function findExtensionManifest(ctx) {
  return ctx.tracked.find((f) => {
    if (!f.endsWith('manifest.json')) return false;
    const text = ctx.read(f);
    return text !== null && /"manifest_version"/.test(text);
  }) ?? null;
}
import { parseYaml } from './minimal-yaml.mjs';

// Every resource across the repo's tracked SAM templates, parsed.
// Returns [{ templatePath, name, resource }].
export function samResources(ctx) {
  const out = [];
  for (const f of ctx.tracked.filter((p) => /(^|\/)template\.ya?ml$/.test(p))) {
    const doc = parseYaml(ctx.read(f) || '');
    const res = doc && typeof doc === 'object' ? doc.Resources : null;
    if (res && typeof res === 'object' && !Array.isArray(res)) {
      for (const [name, resource] of Object.entries(res)) {
        if (resource && typeof resource === 'object') out.push({ templatePath: f, name, resource });
      }
    }
  }
  return out;
}
// A MINIMAL YAML-subset parser — dependency-free, sufficient to query the
// STRUCTURE of SAM/CloudFormation templates (nested block maps, block and flow
// sequences, scalars). Deliberately NOT a general YAML parser:
//   - no anchors/aliases, no multi-line block scalars (| >), no flow maps
//   - CloudFormation short tags (!Ref, !Sub, !GetAtt …) keep their scalar value,
//     the tag is dropped
//   - it never throws: on anything it can't parse it returns what it has (or null)
// Good enough for the SAM/CloudFormation template checks; do not use it for
// arbitrary YAML.

function stripComment(line) {
  let q = null;
  for (let i = 0; i < line.length; i += 1) {
    const c = line[i];
    if (q) { if (c === q) q = null; continue; }
    if (c === '"' || c === "'") { q = c; continue; }
    if (c === '#' && (i === 0 || /\s/.test(line[i - 1]))) return line.slice(0, i);
  }
  return line;
}

function scalar(rawIn) {
  let raw = rawIn.trim();
  if (raw === '' || raw === '~' || raw === 'null') return null;
  if (raw === 'true') return true;
  if (raw === 'false') return false;
  if (raw[0] === '!') {
    // CloudFormation tag: drop the tag word, keep the value
    const sp = raw.indexOf(' ');
    raw = sp === -1 ? '' : raw.slice(sp + 1).trim();
    if (raw === '') return null;
  }
  if ((raw[0] === '"' && raw.at(-1) === '"') || (raw[0] === "'" && raw.at(-1) === "'")) {
    return raw.slice(1, -1);
  }
  if (raw[0] === '[') return flowSeq(raw);
  if (/^-?\d+$/.test(raw)) return Number(raw);
  if (/^-?\d*\.\d+$/.test(raw)) return Number(raw);
  return raw;
}

function flowSeq(raw) {
  const inner = raw.slice(1, raw.lastIndexOf(']')).trim();
  if (inner === '') return [];
  return inner.split(',').map((s) => scalar(s.trim()));
}

const isSeq = (t) => t === '-' || t.startsWith('- ');

// Parse the block whose sibling lines all sit at lines[i].indent; returns [value, next].
function parseBlock(lines, i) {
  const indent = lines[i].indent;

  if (isSeq(lines[i].text)) {
    const arr = [];
    while (i < lines.length && lines[i].indent === indent && isSeq(lines[i].text)) {
      const rest = lines[i].text === '-' ? '' : lines[i].text.slice(2).trim();
      if (rest === '') {
        if (i + 1 < lines.length && lines[i + 1].indent > indent) {
          const [v, ni] = parseBlock(lines, i + 1); arr.push(v); i = ni;
// The four manifest keys that request store-reviewed capabilities. The store
// wants a written justification for every one (required and optional alike),
// and the privacy policy must disclose what each accesses — so both the
// privacy-alignment and permission-added checks read the same set.
export const PERMISSION_KEYS = [
  'permissions',
  'host_permissions',
  'optional_permissions',
  'optional_host_permissions',
];

export function requestedPermissions(manifest) {
  return PERMISSION_KEYS.flatMap((k) => (Array.isArray(manifest[k]) ? manifest[k] : []));
}

