1	#!/usr/bin/env node
2	// Resolves a Chrome-extension repo's release configuration and prints it as
3	// GitHub Actions step outputs. Runs inside the CALLING repo's checkout (the
4	// reusable release workflows invoke it via the read-release-config composite
5	// action), so it reads the caller's own `.github/release.config`.
6	//
7	// `.github/release.config` is a dotenv-style file (KEY=value, `#` comments,
8	// blank lines ignored) and is REQUIRED — every key is mandatory, there are no
9	// silent defaults (a default that "happens to match" a repo's layout is exactly
10	// the drift risk this design avoids). A missing file or a missing/unknown key
11	// fails the run loudly. Required keys:
12	//
13	//   manifest_path       the extension manifest (the version source of truth)
14	//   package_json_path   the package.json kept in sync with the manifest
15	//   setup_command       dependency-install command ("" = no install, stated)
16	//   test_command        the full release test gate
17	//   ship_paths          space-separated shipped roots (the daily change filter)
18	//
19	// Two things are NOT keys because they are FORCED-uniform structure, not a
20	// per-repo choice: the build is always `npm run build`, and the zip lives at the
21	// standard place/name `dist/<kebab repo name>.zip` (derived here as `zip_path` +
22	// `zip_name`). A repo's build must write there.
23	//
24	// Env: REPO_NAME (github.event.repository.name) for the zip derivation;
25	// GITHUB_OUTPUT for the sink. Dependency-free (node: built-ins only).
26	
27	import { readFileSync, existsSync, appendFileSync } from 'node:fs';
28	
29	const CONFIG_PATH = '.github/release.config';
30	
31	const REQUIRED_KEYS = [
32	  'manifest_path',
33	  'package_json_path',
34	  'setup_command',
35	  'test_command',
36	  'ship_paths',
37	];
38	
39	function fail(msg) {
40	  console.error(`read-release-config: ${msg}`);
41	  process.exit(1);
42	}
43	
44	// PascalCase / camelCase / ALLCAPS repo name -> kebab, for the standard zip name
45	// (GoogleCalendarEventCreator -> google-calendar-event-creator,
46	// CrosswordChat -> crossword-chat, TLDR -> tldr).
47	function kebab(name) {
48	  return name
49	    .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
50	    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1-$2')
51	    .toLowerCase();
52	}
53	
54	// setup_command may be empty (an explicit "no install") — present-but-empty is
55	// valid, absent is not.
56	function parseConfig(text) {
57	  const cfg = {};
58	  text.split('\n').forEach((raw, i) => {
59	    const line = raw.trim();
60	    if (!line || line.startsWith('#')) return;
61	    const eq = line.indexOf('=');
62	    if (eq === -1) fail(`${CONFIG_PATH}:${i + 1} is not KEY=value or a # comment: "${line}"`);
63	    const key = line.slice(0, eq).trim();
64	    let value = line.slice(eq + 1).trim();
65	    if (
66	      (value.startsWith('"') && value.endsWith('"')) ||
67	      (value.startsWith("'") && value.endsWith("'"))
68	    ) {
69	      value = value.slice(1, -1);
70	    }
71	    cfg[key] = value;
72	  });
73	  return cfg;
74	}
75	
76	const repoName = process.env.REPO_NAME;
77	if (!repoName) fail('REPO_NAME env is required (github.event.repository.name).');
78	
79	if (!existsSync(CONFIG_PATH)) {
80	  fail(`${CONFIG_PATH} is required — every extension repo declares its release config explicitly (see the chrome-extension-release standard in Claudinite).`);
81	}
82	
83	const cfg = parseConfig(readFileSync(CONFIG_PATH, 'utf8'));
84	
85	const missing = REQUIRED_KEYS.filter((k) => !(k in cfg));
86	if (missing.length) fail(`${CONFIG_PATH} is missing required key(s): ${missing.join(', ')}`);
87	
88	const unknown = Object.keys(cfg).filter((k) => !REQUIRED_KEYS.includes(k));
89	if (unknown.length) fail(`${CONFIG_PATH} has unknown key(s): ${unknown.join(', ')} (valid: ${REQUIRED_KEYS.join(', ')})`);
90	
91	const zipName = `${kebab(repoName)}.zip`;
92	
93	const outputs = {
94	  manifest_path: cfg.manifest_path,
95	  package_json_path: cfg.package_json_path,
96	  setup_command: cfg.setup_command,
97	  test_command: cfg.test_command,
98	  ship_paths: cfg.ship_paths,
99	  // Forced-uniform structure: the build writes the zip here.
100	  zip_name: zipName,
101	  zip_path: `dist/${zipName}`,
102	};
103	
104	const sink = process.env.GITHUB_OUTPUT;
105	if (!sink) {
106	  for (const [k, v] of Object.entries(outputs)) console.log(`${k}=${v}`);
107	  process.exit(0);
108	}
109	
110	let block = '';
111	for (const [k, v] of Object.entries(outputs)) {
112	  block += `${k}<<__RELEASE_CFG__\n${v}\n__RELEASE_CFG__\n`;
113	}
114	appendFileSync(sink, block);

